import { resetCanvasserApplicationSection } from '~/client';
import type { CanvasserSection, UserDetailsResponse, ResetCanvasserApplicationSectionResponse } from '~/client';

export const useRemoveCanvasserInto = defineMutation(() => {
  const queryCache = useQueryCache();
  const { userId } = useUserRole();
  const { getSession } = useAuth();

  const { mutateAsync: removeCanvasserInfo, asyncStatus } = useMutation({
    mutation: (data: {
      userId: string;
      section: CanvasserSection;
    }): Promise<ResetCanvasserApplicationSectionResponse> =>
      resetCanvasserApplicationSection({
        composable: '$fetch',
        path: { user_id: data.userId, section: data.section },
      }),
    onSuccess: async (newData, data) => {
      queryCache.setQueryData(['user', data.userId], (oldData?: UserDetailsResponse) => {
        const key = `canvasser_${data.section}` as keyof UserDetailsResponse;
        const updated: UserDetailsResponse = {
          ...oldData!,
          [key]: null,
        };
        // Advance the matching audit line so the "Last updated …" text reflects the clear
        // immediately, instead of showing the stale pre-clear value until the next refetch.
        const audit = { updated_at: new Date().toISOString(), updated_by: userId.value ?? null };
        if (data.section === 'profile') {
          updated.canvasser_profile_audit = audit;
        } else if (data.section === 'general_info') {
          updated.canvasser_general_info_audit = audit;
        }
        return updated;
      });

      // When clearing your own profile, refresh the auth session (sidebar/header) and the
      // account page's profile card (['account']) so both reflect the cleared state.
      if (data.section === 'profile' && data.userId === userId.value) {
        await getSession();
        await queryCache.invalidateQueries({ key: ['account'], exact: true });
      }
    },
  });

  return {
    removeCanvasserInfo,
    isRemovingCanvasserInfo: computed(() => asyncStatus.value === 'loading'),
  };
});
